<?php declare(strict_types=1); ?>
<header class="page-header"><div><h1>Mitglieder</h1><p>Stammdaten, Kontakte und Einwilligungen zentral verwalten.</p></div><div class="header-actions"><button class="button button-secondary" type="button" data-coming-soon="true"><svg><use href="#i-upload"/></svg>Importieren</button><button class="button button-primary" type="button" data-dialog-open="member-dialog"><svg><use href="#i-plus"/></svg>Mitglied anlegen</button></div></header>
