<?php if ($members === []): ?><tr><td class="empty-cell" colspan="8">Keine Mitglieder für diese Auswahl gefunden.</td></tr><?php endif; ?>
<?php foreach ($members as $member): ?><tr class="<?= (int)($selected['id']??0)===(int)$member['id']?'is-selected':'' ?>" data-row-link="/members?member=<?= (int)$member['id'] ?>"><td><strong><?= e($member['first_name'].' '.$member['last_name']) ?></strong></td><td><?= $member['member_type']==='staff'?'Betreuer/in':'Jugendmitglied' ?></td><td><?= e(age_from_birthdate($member['birth_date'])) ?></td><td><?= e(german_date($member['entry_date'])) ?></td><td><?= e($member['email'] ?: $member['phone'] ?: '–') ?></td><td><span class="consent-count <?= (int)$member['consents_granted'] < (int)$member['consents_total'] ? 'has-open' : '' ?>"><?= (int)$member['consents_granted'] ?> / <?= (int)$member['consents_total'] ?></span></td><td><span class="dot dot-<?= e($member['status_name']) ?>"></span><?= $member['status_name']==='active'?'Aktiv':($member['status_name']==='paused'?'Pausiert':'Ausgetreten') ?></td><td><a class="row-action" href="/members?member=<?= (int)$member['id'] ?>" aria-label="Details öffnen">•••</a></td></tr><?php endforeach; ?>
</tbody></table></div><footer class="list-footer"><span>1–<?= count($members) ?> von <?= count($members) ?> Mitgliedern</span><span>25 Einträge pro Seite</span></footer></section>
<?php if ($selected): ?><aside class="detail-drawer"><header><h2><?= e($selected['first_name'].' '.$selected['last_name']) ?></h2><a class="icon-button" href="/members" aria-label="Schließen"><svg><use href="#i-close"/></svg></a></header><div class="person-summary"><span class="avatar avatar-large"><?= e(initials($selected['first_name'],$selected['last_name'])) ?></span><div><h3><?= e($selected['first_name'].' '.$selected['last_name']) ?></h3><span class="member-active"><i></i>Aktiv</span><p><?= $selected['member_type']==='staff'?'Betreuer/in':'Jugendmitglied' ?> · <?= e(age_from_birthdate($selected['birth_date'])) ?> Jahre<br>Seit <?= e(german_date($selected['entry_date'])) ?></p></div></div>
<section><h3>Kontakt (Erziehungsberechtigte/r)</h3><?php if ($selected['guardian']): ?><p><strong><?= e($selected['guardian']['full_name']) ?></strong><br><?= e($selected['guardian']['phone'] ?: '') ?><br><?= e($selected['guardian']['email'] ?: '') ?></p><?php else: ?><p>Noch kein Kontakt hinterlegt.</p><?php endif; ?></section>
<section><h3>Einwilligungen</h3><?php if ($selected['consents']===[]): ?><p>Noch keine Einwilligungen hinterlegt.</p><?php endif; ?><?php foreach ($selected['consents'] as $consent): ?><div class="drawer-line"><span class="dot dot-<?= $consent['status_name']==='granted'?'active':'paused' ?>"></span><span><strong><?= e($consent['title']) ?></strong><small><?= $consent['status_name']==='granted'?'Erteilt':'Offen' ?></small></span></div><?php endforeach; ?></section>
<footer><button type="button" class="button button-primary button-block" data-dialog-open="member-edit-dialog">Profil bearbeiten</button></footer></aside><?php endif; ?>
