ption value="open">Offen</option><option value="granted">Erteilt</option><option value="declined">Abgelehnt</option></select></label><label class="span-2">Notizen<textarea name="notes_text" rows="3"><?= e($selected['notes_text']??'') ?></textarea></label></div><footer><button type="button" class="button button-secondary" data-dialog-close>Abbrechen</button><button type="submit" class="button button-primary">Änderungen speichern</button></footer></form></dialog><?php endif; ?>
